import{_ as i,o as e,c as t,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-08-28 :: Ceph Science User Group Meeting","description":"","frontmatter":{"title":"2019-08-28 :: Ceph Science User Group Meeting","date":"2019-08-28T00:00:00.000Z","updated":"2019-09-07T00:00:00.000Z","tags":["Ceph","分布式存储","OpenStack","对象存储","块存储","高性能计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-28_-_-_Ceph_Science_User_Group_Meeting.md","filePath":"posts/2019/2019-08-28_-_-_Ceph_Science_User_Group_Meeting.md","lastUpdated":1780460162000}'),s={name:"posts/2019/2019-08-28_-_-_Ceph_Science_User_Group_Meeting.md"};function r(o,l,n,_,a,c){return e(),t("div",null,[...l[0]||(l[0]=[p("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2019年8月28日</p><p><strong>参会人员</strong>： 来自全球多个机构的Ceph用户和开发者，包括美国、英国、瑞士、加拿大等地的大学、研究机构和企业。</p><p><strong>会议主题</strong>：</p><ul><li>Ceph的使用案例和经验分享</li><li>Ceph的性能优化和问题解决</li><li>Ceph的未来发展方向</li><li>Ceph社区建设和活动</li></ul><p><strong>会议内容</strong>：</p><ul><li><strong>Ceph使用案例</strong>： <ul><li>多个机构分享了他们如何使用Ceph作为OpenStack的块存储和对象存储，以及在其科学计算、大数据分析、视频流媒体、备份、高性能计算和数据存储等方面的应用。</li><li>讨论了Ceph在不同场景下的性能优化和问题解决方法，例如使用NVMe硬盘、优化存储池配置、使用性能监控工具等。</li><li>分享了Ceph未来发展方向，如支持更多协议、提高性能、增强安全性等。</li></ul></li><li><strong>Ceph社区建设和活动</strong>： <ul><li>讨论了如何加强Ceph社区建设，包括组织线上和线下活动、建立用户交流平台等。</li><li>计划在瑞士日内瓦举办Ceph Day活动，并邀请Ceph用户和开发者参加。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>继续组织Ceph用户会议，分享经验和讨论问题。</li><li>加强Ceph社区建设，建立用户交流平台。</li><li>在瑞士日内瓦举办Ceph Day活动。</li><li>推动Ceph的发展，提高其性能和安全性。</li></ul><p><strong>关键词</strong>：</p><ul><li>Ceph</li><li>OpenStack</li><li>对象存储</li><li>块存储</li><li>高性能计算</li><li>数据备份</li><li>数据共享</li><li>社区建设</li><li>分布式存储</li><li>CRUSH算法</li><li>高可用性</li><li>可伸缩性</li><li>对象存储</li><li>块存储</li><li>文件系统存储</li><li>一致性</li><li>去中心化</li><li>性能</li><li>bluestore</li><li>bluefs</li><li>rocksdb</li><li>OSD</li><li>MON</li><li>MDS</li><li>PG</li><li>RADOS</li><li>librados</li><li>libcephfs</li><li>cephfs</li><li>rbd</li><li>radosgw</li><li>RGW</li><li>RESTful API</li><li>认证</li><li>授权</li><li>加密</li><li>损坏纠正码</li><li>复制</li><li>快照</li><li>克隆</li><li>虚拟化</li><li>云计算</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>混合云</li><li>多云</li><li>存储集群</li><li>节点</li><li>硬盘</li><li>SSD</li><li>HDD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>网络</li><li>拓扑</li><li>失败域</li><li>恢复</li><li>弹性</li><li>负载均衡</li><li>缓存</li><li>压缩</li><li>去重</li><li>分层</li><li>性能调优</li><li>基准测试</li><li>测试</li><li>验证</li></ul>",11)])])}const h=i(s,[["render",r]]);export{g as __pageData,h as default};
